def is_sum_free_with_new_element(current_set, new_element):
    # Check if new_element can be added to current_set such that it remains sum-free
    # A set S is sum-free if x+y=z has no solution in S.
    # Since we add elements in increasing order, the only new solutions
    # could involve the new_element as the 'z' (i.e., x+y = new_element).
    # Or if new_element is one of the 'x' or 'y', then x+new_element = z.
    # But z > new_element, so z is not in the set yet.
    # Thus we only need to check if x+y = new_element for x, y in S (including x=y).
    for x in current_set:
        if x + x == new_element:
            return False
        y = new_element - x
        if y != x and y in current_set:
            return False
    return True

def solve_f(k, n):
    # partition[i] = color of element i (0 to k-1)
    partition = [-1] * (n + 1)
    sets = [[] for _ in range(k)]

    def backtrack(curr):
        if curr > n:
            return True

        for color in range(k):
            if is_sum_free_with_new_element(sets[color], curr):
                sets[color].append(curr)
                partition[curr] = color
                if backtrack(curr + 1):
                    return True
                partition[curr] = -1
                sets[color].pop()
        return False

    if backtrack(1):
        return True
    return False

