def is_sum_free(subset):
    s_set = set(subset)
    for x in subset:
        for y in subset:
            if x + y in s_set:
                return False
    return True

def can_partition(current_n, k, partition):
    if current_n == 0:
        return True

    for i in range(k):
        partition[i].append(current_n)

        valid = True
        # Optimized check
        # We're adding current_n, which is the smallest number so far.
        # The only way the set becomes not sum-free is if:
        # 1. current_n + x = y for some x, y in the set
        # 2. current_n + current_n = z for some z in the set
        for x in partition[i]:
            if x != current_n and (current_n + x) in partition[i]:
                valid = False
                break
        if valid:
            if (2 * current_n) in partition[i]:
                valid = False

        if valid:
            if can_partition(current_n - 1, k, partition):
                return True
        partition[i].pop()
    return False

