print(f"Time taken: {time.time() - start}")

def is_sum_free(s):
    for x in s:
        for y in s:
            if x + y in s:
                return False
    return True

def find_partition(n, k):
    partition = [set() for _ in range(k)]

    def backtrack(num):
        if num == 0:
            return True
        for i in range(k):
            partition[i].add(num)
            if is_sum_free(partition[i]):
                if backtrack(num - 1):
                    return True
            partition[i].remove(num)
        return False

    if backtrack(n):
        return partition
    return None

