import random

def solve():
    n = 40
    m = 4
    partition = [[] for _ in range(m)]

    def is_sum_free(current_set, new_element):
        for x in current_set:
            if x + x == new_element:
                return False
            for y in current_set:
                if x + y == new_element:
                    return False
        return True

    for i in range(1, n + 1):
        placed = False
        indices = list(range(m))
        random.shuffle(indices)
        for j in indices:
            if is_sum_free(partition[j], i):
                partition[j].append(i)
                placed = True
                break
        if not placed:
            return None
    return partition

